mapper.select:
SELECT h.*, s.school_name, m.school_major_name FROM school_historical_score h LEFT JOIN school_info s ON h.school_historical_score_school_id = s.school_id LEFT JOIN school_major m ON h.school_historical_score_major_id = m.school_major_id WHERE h.school_historical_score_school_id = #{schoolId} AND h.school_historical_score_deleted = 0
AND h.school_historical_score_province = #{province}
AND h.school_historical_score_subject_type = #{subjectType}
ORDER BY h.school_historical_score_year DESC, h.school_historical_score_province ASC, h.school_historical_score_subject_type ASC, h.school_historical_score_batch ASC

SELECT h.*, s.school_name, m.school_major_name FROM school_historical_score h LEFT JOIN school_info s ON h.school_historical_score_school_id = s.school_id LEFT JOIN school_major m ON h.school_historical_score_major_id = m.school_major_id WHERE h.school_historical_score_major_id = #{majorId} AND h.school_historical_score_deleted = 0
AND h.school_historical_score_province = #{province}
AND h.school_historical_score_subject_type = #{subjectType}
ORDER BY h.school_historical_score_year DESC, h.school_historical_score_province ASC, h.school_historical_score_subject_type ASC, h.school_historical_score_batch ASC

SELECT h.*, s.school_name, m.school_major_name FROM school_historical_score h LEFT JOIN school_info s ON h.school_historical_score_school_id = s.school_id LEFT JOIN school_major m ON h.school_historical_score_major_id = m.school_major_id
AND h.school_historical_score_deleted = 0
AND h.school_historical_score_school_id = #{schoolId}
AND h.school_historical_score_major_id = #{majorId}
AND h.school_historical_score_province = #{province}
AND h.school_historical_score_subject_type = #{subjectType}
AND h.school_historical_score_year = #{year}
ORDER BY h.school_historical_score_year DESC, h.school_historical_score_province ASC, h.school_historical_score_subject_type ASC, h.school_historical_score_batch ASC
